","const CUST_BASE = "/api/now/table/x_2056099_indust_0_cust_master";

async function api(url: string) {
 const res = await fetch(url, {
 headers: {
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 });
 if (!res.ok) throw new Error(`API ${res.status}`);
 return res.json();
}

/**
 * Fetch customer record linked to the current logged-in user.
 * Falls back to the first active customer if no direct link is found.
 */
export async function fetchCurrentCustomer() {
 // First try: find customer whose primary_contact_email matches the logged-in user
 const userSysId = (window as any).NOW?.user?.userID || "";
 if (userSysId) {
 // Check sys_user for email
 const userRes = await api(
 `/api/now/table/sys_user/${userSysId}?sysparm_fields=email,name`
 );
 const email = userRes.result?.email;
 if (email) {
 const custRes = await api(
 `${CUST_BASE}?sysparm_display_value=all&sysparm_query=primary_contact_email=${encodeURIComponent(email)}^active=true&sysparm_limit=1`
 );
 if (custRes.result?.length) return custRes.result[0];
 }
 }
 // Fallback: return first active customer
 const fallback = await api(
 `${CUST_BASE}?sysparm_display_value=all&sysparm_query=active=true&sysparm_limit=1`
 );
 return fallback.result?.[0] || null;
}

export async function fetchCustomer(sysId: string) {
 const data = await api(
 `${CUST_BASE}/${sysId}?sysparm_display_value=all`
 );
 return data.result;
}
","export const display = (field: any) => field?.display_value || "";
export const value = (field: any) => field?.value || "";

/** Map UOM choice value to display label */
export function formatUom(uom: string): string {
 const v = (uom || "").toLowerCase().trim();
 if (v === "kg") return "Kg";
 if (v === "litres") return "Litre";
 if (v === "metres") return "Metre";
 return "Unit";
}

/** Format currency for display */
export function formatCurrency(amount: number | string): string {
 const n = typeof amount === "string" ? parseFloat(amount) : amount;
 if (isNaN(n)) return "₹0.00";
 return "₹" + n.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
