","import React, { useState, useEffect } from "react";
import { fetchOrders, fetchOrderItems } from "../../services/orderService";
import { fetchCurrentCustomer } from "../../services/customerService";
import { value } from "../../utils/fields";
import DashKpiCards from "./dashboard/DashKpiCards";
import CurrentOrderPanel from "./dashboard/CurrentOrderPanel";
import NextDeliveryPanel from "./dashboard/NextDeliveryPanel";
import RecentOrdersPanel from "./dashboard/RecentOrdersPanel";
import BestSellingPanel from "./dashboard/BestSellingPanel";
import OrderStatusPanel from "./dashboard/OrderStatusPanel";
import DelayedOrdersPanel from "./dashboard/DelayedOrdersPanel";

export default function DashboardSection() {
 const [orders, setOrders] = useState<any[]>([]);
 const [orderItems, setOrderItems] = useState<any[]>([]);
 const [customer, setCustomer] = useState<any>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 (async () => {
 try {
 const cust = await fetchCurrentCustomer();
 setCustomer(cust);
 const custId = cust?.sys_id?.value || cust?.sys_id || "";
 const q = custId ? `customer=${custId}^ORDERBYDESCorder_date` : "ORDERBYDESCorder_date";
 const [ords, items] = await Promise.all([
 fetchOrders(q),
 custId
 ? fetchOrderItems(`customer_order.customer=${custId}`)
 : fetchOrderItems(""),
 ]);
 setOrders(ords);
 setOrderItems(items);
 } catch (e) {
 console.error("Dashboard load error", e);
 } finally {
 setLoading(false);
 }
 })();
 }, []);

 if (loading) {
 return <div className="dash-loading">Loading dashboard…</div>;
 }

 /* Compute KPIs */
 const totalOrders = orders.length;
 const activeStatuses = ["submitted", "under_validation", "approved", "in_production", "partially_completed"];
 const activeOrders = orders.filter((o: any) => activeStatuses.includes(value(o.status)));
 const inProduction = orders.filter((o: any) => value(o.status) === "in_production");
 const completedOrders = orders.filter(
 (o: any) => value(o.status) === "completed" || value(o.status) === "partially_completed"
 );

 /* Most relevant active order (newest active) */
 const currentOrder = activeOrders[0] || null;

 /* Next delivery: soonest future requested_delivery_date among active orders */
 const now = new Date();
 const upcomingOrders = activeOrders
 .filter((o: any) => {
 const d = value(o.requested_delivery_date);
 return d && new Date(d) >= now;
 })
 .sort(
 (a: any, b: any) =>
 new Date(value(a.requested_delivery_date)).getTime() -
 new Date(value(b.requested_delivery_date)).getTime()
 );
 const nextDeliveryOrder = upcomingOrders[0] || null;

 /* Recent orders — latest 5 */
 const recentOrders = orders.slice(0, 5);

 /* Best selling products from order items */
 const productMap: Record<string, { name: string; totalQty: number }> = {};
 orderItems.forEach((item: any) => {
 const pName =
 item.material_product?.display_value || value(item.material_product) || "Unknown";
 const pId = value(item.material_product);
 const qty = parseFloat(value(item.quantity_ordered)) || 0;
 if (productMap[pId]) {
 productMap[pId].totalQty += qty;
 } else {
 productMap[pId] = { name: pName, totalQty: qty };
 }
 });
 const bestSelling = Object.entries(productMap)
 .map(([id, data]) => ({ id, ...data }))
 .sort((a, b) => b.totalQty - a.totalQty)
 .slice(0, 5);

 /* Delayed orders: past delivery date + still active */
 const delayedOrders = activeOrders.filter((o: any) => {
 const d = value(o.requested_delivery_date);
 return d && new Date(d) < now;
 });

 /* Status distribution */
 const statusCounts: Record<string, number> = {};
 orders.forEach((o: any) => {
 const s = o.status?.display_value || value(o.status) || "Unknown";
 statusCounts[s] = (statusCounts[s] || 0) + 1;
 });

 return (
 <div className="cust-dashboard">
 <h2 className="section-title">Dashboard</h2>

 <DashKpiCards
 totalOrders={totalOrders}
 activeOrders={activeOrders.length}
 inProduction={inProduction.length}
 completed={completedOrders.length}
 />

 <div className="dash-grid">
 <CurrentOrderPanel order={currentOrder} />
 <NextDeliveryPanel order={nextDeliveryOrder} />
 </div>

 <div className="dash-grid">
 <RecentOrdersPanel orders={recentOrders} />
 <BestSellingPanel products={bestSelling} />
 </div>

 <div className="dash-grid">
 <OrderStatusPanel statusCounts={statusCounts} total={totalOrders} />
 <DelayedOrdersPanel orders={delayedOrders} />
 </div>
 </div>
 );
}
