export async function fetchProducts(query = "") {
 const q = query
 ? `&sysparm_query=${encodeURIComponent(query)}`
 : "&sysparm_query=active=true^category=finished_product";
 const data = await api(
 `${BASE}?sysparm_display_value=all&sysparm_limit=200${q}`
 );
 return data.result || [];
}

export async function fetchProduct(sysId: string) {
 const data = await api(
 `${BASE}/${sysId}?sysparm_display_value=all`
 );
 return data.result;
}
