 onBack: () => void;
}

export default function ProductDetail({ productId, onBack }: Props) {
 const [product, setProduct] = useState<any>(null);
 const [loading, setLoading] = useState(true);
 const [quantity, setQuantity] = useState(1);
 const [added, setAdded] = useState(false);
 const { addItem } = useCart();

 useEffect(() => {
 (async () => {
 try {
 const p = await fetchProduct(productId);
 setProduct(p);
 } catch (e) {
 console.error("Load product error", e);
 } finally {
 setLoading(false);
 }
 })();
 }, [productId]);

 if (loading) return <div className="loading">Loading product…</div>;
 if (!product) return <div className="error">Product not found</div>;

 const name = display(product.name);
 const desc = display(product.description);
 const cost = parseFloat(value(product.standard_cost)) || 0;
 const uom = value(product.unit_of_measure);
 const uomLabel = formatUom(uom);
 const lineTotal = cost * quantity;
 const category = display(product.category);
 const materialId = display(product.material_product_id);
 const criticality = display(product.criticality);

 const handleAddToCart = () => {
 if (quantity <= 0) return;
 addItem({
 productId: value(product.sys_id),
 productName: name,
 unitCost: cost,
 uom,
 quantity,
 });
 setAdded(true);
 setTimeout(() => setAdded(false), 2000);
 };

 return (
 <div className="product-detail">
 <button className="back-btn" onClick={onBack}>← Back to Catalog</button>

 <div className="pd-header">
 <h2>{name}</h2>
 <span className="pd-id">{materialId}</span>
 </div>

 <div className="pd-body">
 <div className="pd-info">
 <div className="pd-row">
 <span className="pd-label">Category</span>
 <span className="pd-value">{category}</span>
 </div>
 <div className="pd-row">
 <span className="pd-label">Criticality</span>
 <span className="pd-value">{criticality}</span>
 </div>
 <div className="pd-row">
 <span className="pd-label">Unit of Measure</span>
 <span className="pd-value">{uomLabel}</span>
 </div>
 <div className="pd-row">
 <span className="pd-label">Description</span>
 <span className="pd-value">{desc || "—"}</span>
 </div>
 </div>

 <div className="pd-pricing">
 <div className="pd-price">
 <span className="price-amount">{formatCurrency(cost)}</span>
 <span className="price-uom">per {uomLabel}</span>
 </div>

 <div className="pd-quantity">
 <label htmlFor="qty-input">Quantity:</label>
 <input
 id="qty-input"
 type="number"
 min={1}
 value={quantity}
 onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
 className="qty-input"
 />
 <span className="qty-uom">{uomLabel}</span>
 </div>

 <div className="pd-line-total">
 <span className="lt-label">Line Total:</span>
 <span className="lt-value">{formatCurrency(lineTotal)}</span>
 </div>

 <button className="add-cart-btn" onClick={handleAddToCart} disabled={quantity <= 0}>
 {added ? "✓ Added to Cart" : "Add to Cart"}
 </button>
 </div>
 </div>
 </div>
 );
}
","import React, { useState } from "react";
import { useCart } from "../contexts/CartContext";
import { formatUom, formatCurrency } from "../utils/fields";

interface Props {
 product: any;
 onClose: () => void;
}

export default function AddToCartForm({ product, onClose }: Props) {
 const [quantity, setQuantity] = useState(1);
 const [error, setError] = useState("");
 const { addItem } = useCart();

 const name = product.name?.display_value || product.name?.value || "";
 const cost = parseFloat(product.standard_cost?.value || "0");
 const uom = product.unit_of_measure?.value || "";
 const uomLabel = formatUom(uom);
 const lineTotal = cost * quantity;

 const handleSubmit = () => {
 if (quantity <= 0) {
 setError("Please enter a quantity greater than 0");
 return;
 }
 addItem({
 productId: product.sys_id?.value || "",
 productName: name,
 unitCost: cost,
 uom,
 quantity,
 });
 onClose();
 };

 return (
 <div className="add-cart-form-overlay" onClick={onClose}>
 <div className="add-cart-form" onClick={(e) => e.stopPropagation()}>
 <h3>Add to Cart</h3>
 <p className="acf-product-name">{name}</p>

 <div className="acf-price">
 {formatCurrency(cost)} per {uomLabel}
 </div>

 <div className="acf-quantity">
 <label htmlFor="acf-qty">Quantity ({uomLabel}):</label>
 <input
 id="acf-qty"
 type="number"
 min={1}
 value={quantity}
 onChange={(e) => {
 const v = parseInt(e.target.value) || 0;
 setQuantity(v);
 setError(v <= 0 ? "Quantity must be greater than 0" : "");
 }}
 />
 </div>

 {error && <p className="acf-error">{error}</p>}

 <div className="acf-line-total">
 <span>Line Total:</span>
 <strong>{formatCurrency(lineTotal)}</strong>
 </div>

 <div className="acf-actions">
 <button className="btn-secondary" onClick={onClose}>Cancel</button>
 <button className="btn-primary" onClick={handleSubmit} disabled={quantity <= 0}>
 Add to Cart
 </button>
 </div>
 </div>
 </div>
 );
}
","import React, { useState, useEffect } from "react";
import { fetchProducts } from "../../services/productService";
import StorefrontCard from "../StorefrontCard";
import ProductDetail from "../ProductDetail";
import AddToCartForm from "../AddToCartForm";

export default function CatalogSection() {
 const [products, setProducts] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [search, setSearch] = useState("");
 const [selectedId, setSelectedId] = useState<string | null>(null);
 const [addToCartProduct, setAddToCartProduct] = useState<any>(null);

 useEffect(() => {
 loadProducts();
 }, []);

 const loadProducts = async (q = "") => {
 setLoading(true);
 try {
 const query = q
 ? `active=true^category=finished_product^nameLIKE${q}`
 : "";
 const data = await fetchProducts(query);
 setProducts(data);
 } catch (e) {
 console.error("Load products error", e);
 } finally {
 setLoading(false);
 }
 };

 const handleSearch = () => {
 loadProducts(search);
 };

 if (selectedId) {
 return (
 <ProductDetail productId={selectedId} onBack={() => setSelectedId(null)} />
 );
 }

 return (
 <div className="catalog-section">
 <h2 className="section-title">Product Catalog</h2>

 <div className="catalog-search">
 <input
 type="text"
 placeholder="Search products..."
 value={search}
 onChange={(e) => setSearch(e.target.value)}
 onKeyDown={(e) => e.key === "Enter" && handleSearch()}
 />
 <button className="btn-primary" onClick={handleSearch}>Search</button>
 </div>

 {loading ? (
 <div className="loading">Loading products…</div>
 ) : products.length === 0 ? (
 <div className="catalog-empty">No products found</div>
 ) : (
 <div className="storefront-grid">
 {products.map((p: any) => (
 <div key={p.sys_id?.value}>
 <StorefrontCard
 product={p}
 onSelect={(id) => setSelectedId(id)}
 onAddToCart={(prod) => setAddToCartProduct(prod)}
 />
 </div>
 ))}
 </div>
 )}

 {addToCartProduct && (
 <AddToCartForm
 product={addToCartProduct}
 onClose={() => setAddToCartProduct(null)}
 />
 )}
 </div>
 );
}
