export default function MyOrdersSection() {
 const [orders, setOrders] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [selectedId, setSelectedId] = useState<string | null>(null);
 const [filter, setFilter] = useState("all");

 useEffect(() => {
 (async () => {
 try {
 const cust = await fetchCurrentCustomer();
 const custId = cust?.sys_id?.value || cust?.sys_id || "";
 const q = custId
 ? `customer=${custId}^ORDERBYDESCorder_date`
 : "ORDERBYDESCorder_date";
 const data = await fetchOrders(q);
 setOrders(data);
 } catch (e) {
 console.error("Load orders error", e);
 } finally {
 setLoading(false);
 }
 })();
 }, []);

 if (selectedId) {
 return (
 <OrderDetailView orderId={selectedId} onBack={() => setSelectedId(null)} />
 );
 }

 const filtered =
 filter === "all"
 ? orders
 : orders.filter((o: any) => value(o.status) === filter);

 return (
 <div className="orders-section">
 <h2 className="section-title">My Orders</h2>

 <div className="order-filters">
 {["all", "draft", "submitted", "approved", "in_production", "completed", "cancelled"].map(
 (f) => (
