 key={f}
 className={`filter-btn ${filter === f ? "active" : ""}`}
 onClick={() => setFilter(f)}
 >
 {f === "all" ? "All" : f.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())}
 </button>
 )
 )}
 </div>

 {loading ? (
 <div className="loading">Loading orders…</div>
 ) : (
 <OrderListView orders={filtered} onSelect={(id) => setSelectedId(id)} />
 )}
 </div>
 );
}
