","import React from "react";

interface Props {
 status: string;
 daysUntil?: number;
}

export default function DeliveryStatusTag({ status, daysUntil }: Props) {
 let color = "#6c757d";
 let label = status;

 if (daysUntil !== undefined) {
 if (daysUntil < 0) {
 color = "#c23934";
 label = `${Math.abs(daysUntil)}d overdue`;
 } else if (daysUntil === 0) {
 color = "#e87722";
 label = "Due today";
 } else if (daysUntil <= 3) {
 color = "#f39c12";
 label = `${daysUntil}d away`;
 } else {
 color = "#2ecc71";
 label = `${daysUntil}d away`;
 }
 }

 return (
 <span className="delivery-status-tag" style={{ backgroundColor: color, color: "#fff" }}>
 {label}
 </span>
 );
}
