","import React, { useState, useEffect } from "react";
import { fetchOrders } from "../../services/orderService";
import { fetchCurrentCustomer } from "../../services/customerService";
import { value } from "../../utils/fields";
import DeliveryKpis from "./delivery/DeliveryKpis";
import UpcomingDeliveries from "./delivery/UpcomingDeliveries";
import DelayedDeliveries from "./delivery/DelayedDeliveries";

export default function DeliverySection() {
 const [orders, setOrders] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 (async () => {
 try {
 const cust = await fetchCurrentCustomer();
 const custId = cust?.sys_id?.value || cust?.sys_id || "";
 const activeStatuses = "submitted,under_validation,approved,in_production,partially_completed";
 const q = custId
 ? `customer=${custId}^statusIN${activeStatuses}^ORDERBYrequested_delivery_date`
 : `statusIN${activeStatuses}^ORDERBYrequested_delivery_date`;
 const data = await fetchOrders(q);
 setOrders(data);
 } catch (e) {
 console.error("Load deliveries error", e);
 } finally {
 setLoading(false);
 }
 })();
 }, []);

 if (loading) return <div className="loading">Loading delivery data…</div>;

 const now = new Date();
 const upcoming = orders.filter((o: any) => {
 const d = value(o.requested_delivery_date);
 return d && new Date(d) >= now;
 });
 const delayed = orders.filter((o: any) => {
 const d = value(o.requested_delivery_date);
 return d && new Date(d) < now;
 });

 return (
 <div className="delivery-section">
 <h2 className="section-title">Delivery Tracking</h2>
 <DeliveryKpis total={orders.length} upcoming={upcoming.length} delayed={delayed.length} />
 <UpcomingDeliveries orders={upcoming} />
 <DelayedDeliveries orders={delayed} />
 </div>
 );
}
