import { fetchCurrentCustomer } from "../../services/customerService";
import { display, value } from "../../utils/fields";

export default function ProfileSection() {
 const [customer, setCustomer] = useState<any>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 (async () => {
 try {
 const cust = await fetchCurrentCustomer();
 setCustomer(cust);
 } catch (e) {
 console.error("Load profile error", e);
 } finally {
 setLoading(false);
 }
 })();
 }, []);

 if (loading) return <div className="loading">Loading profile…</div>;
 if (!customer) return <div className="error">No customer profile found</div>;

 const fields = [
 { label: "Customer ID", val: display(customer.customer_id) },
 { label: "Customer Name", val: display(customer.customer_name) },
 { label: "Customer Type", val: display(customer.customer_type) },
 { label: "Industry", val: display(customer.industry) },
 { label: "Email", val: display(customer.primary_contact_email) },
 { label: "Phone", val: display(customer.primary_contact_phone) },
 { label: "Payment Terms", val: display(customer.payment_terms) },
 { label: "Credit Limit", val: display(customer.credit_limit) },
 ];

 return (
 <div className="profile-section">
 <h2 className="section-title">My Profile</h2>

 <div className="profile-card">
 <div className="profile-avatar">👤</div>
 <h3>{display(customer.customer_name)}</h3>

 <div className="profile-details">
 {fields.map((f) => (
 <div key={f.label} className="profile-row">
 <span className="profile-label">{f.label}</span>
 <span className="profile-value">{f.val || "—"}</span>
 </div>
 ))}
 </div>

 {display(customer.notes) && (
 <div className="profile-notes">
 <h4>Notes</h4>
 <p>{display(customer.notes)}</p>
 </div>
 )}
 </div>
 </div>
 );
}
","import React from "react";
import { useCart, CartItem } from "../contexts/CartContext";
import { formatUom, formatCurrency } from "../utils/fields";

export default function CartItemEditor({ item }: { item: CartItem }) {
 const { updateQuantity, removeItem } = useCart();
 const uomLabel = formatUom(item.uom);
 const lineTotal = item.unitCost * item.quantity;

 return (
 <div className="cart-item">
 <div className="ci-info">
 <h4 className="ci-name">{item.productName}</h4>
 <span className="ci-price">
 {formatCurrency(item.unitCost)} per {uomLabel}
 </span>
 </div>
 <div className="ci-controls">
 <button
 className="ci-btn"
 onClick={() => updateQuantity(item.productId, item.quantity - 1)}
 >
 −
 </button>
 <span className="ci-qty">{item.quantity}</span>
 <button
 className="ci-btn"
 onClick={() => updateQuantity(item.productId, item.quantity + 1)}
 >
 +
 </button>
 <span className="ci-uom">{uomLabel}</span>
 </div>
 <div className="ci-line-total">
 <span className="ci-lt-label">Line Total:</span>
 <strong>{formatCurrency(lineTotal)}</strong>
 </div>
 <button className="ci-remove" onClick={() => removeItem(item.productId)}>
 ✕
 </button>
 </div>
 );
}
","import React, { useState } from "react";
import { useCart } from "../contexts/CartContext";
import { createOrder, createOrderItem } from "../services/orderService";
import { fetchCurrentCustomer } from "../services/customerService";
import { formatUom, formatCurrency } from "../utils/fields";

interface Props {
 onBack: () => void;
 onDone: () => void;
}

export default function OrderSummary({ onBack, onDone }: Props) {
 const { items, totalCost, clearCart } = useCart();
 const [submitting, setSubmitting] = useState(false);
 const [error, setError] = useState("");
 const [success, setSuccess] = useState(false);
 const [deliveryDate, setDeliveryDate] = useState("");
 const [deliveryLocation, setDeliveryLocation] = useState("");
 const [instructions, setInstructions] = useState("");

 const handleSubmit = async () => {
 if (!deliveryDate) {
 setError("Please select a delivery date");
 return;
 }
 setSubmitting(true);
 setError("");
 try {
 const customer = await fetchCurrentCustomer();
 const custId = customer?.sys_id?.value || customer?.sys_id || "";

 const totalQty = items.reduce((s, i) => s + i.quantity, 0);

 const order = await createOrder({
 customer: custId,
 order_date: new Date().toISOString(),
 requested_delivery_date: deliveryDate,
 delivery_location: deliveryLocation,
 special_instructions: instructions,
 status: "draft",
 priority: "medium",
 order_type: "standard",
 total_order_quantity: totalQty,
 });

 const orderId = order?.sys_id?.value || order?.sys_id;

 // Create order items
 for (const item of items) {
 await createOrderItem({
 customer_order: orderId,
 material_product: item.productId,
 quantity_ordered: item.quantity,
 unit_of_measure: item.uom || "nos",
 item_status: "pending",
 priority: "medium",
 });
 }

 clearCart();
 setSuccess(true);
 } catch (e: any) {
 console.error("Order submit error", e);
 setError(e.message || "Failed to submit order");
 } finally {
 setSubmitting(false);
 }
 };

 if (success) {
 return (
 <div className="order-success">
 <h2>✅ Order Submitted!</h2>
 <p>Your order has been created successfully.</p>
 <button className="btn-primary" onClick={onDone}>Back to Portal</button>
 </div>
 );
 }

 return (
 <div className="order-summary">
 <button className="back-btn" onClick={onBack}>← Back to Cart</button>
 <h2 className="section-title">Order Summary</h2>

 <div className="os-items">
 <table className="dash-table">
 <thead>
 <tr>
 <th>Product</th>
 <th>Qty</th>
 <th>Unit Price</th>
 <th>Line Total</th>
 </tr>
 </thead>
 <tbody>
 {items.map((item) => (
 <tr key={item.productId}>
 <td>{item.productName}</td>
 <td>
 {item.quantity} {formatUom(item.uom)}
 </td>
 <td>{formatCurrency(item.unitCost)}</td>
 <td>{formatCurrency(item.unitCost * item.quantity)}</td>
 </tr>
 ))}
 </tbody>
 </table>
 <div className="os-total">
 <strong>Total: {formatCurrency(totalCost)}</strong>
 </div>
 </div>

 <div className="os-form">
 <div className="os-field">
 <label htmlFor="os-date">Requested Delivery Date *</label>
 <input
 id="os-date"
 type="date"
 value={deliveryDate}
 onChange={(e) => setDeliveryDate(e.target.value)}
 />
 </div>
 <div className="os-field">
 <label htmlFor="os-location">Delivery Location</label>
 <input
 id="os-location"
 type="text"
 value={deliveryLocation}
 onChange={(e) => setDeliveryLocation(e.target.value)}
 placeholder="Delivery address"
 />
 </div>
 <div className="os-field">
 <label htmlFor="os-instr">Special Instructions</label>
 <textarea
 id="os-instr"
 value={instructions}
 onChange={(e) => setInstructions(e.target.value)}
 placeholder="Any special requirements..."
 />
 </div>
 </div>

 {error && <p className="os-error">{error}</p>}

 <div className="os-actions">
 <button className="btn-secondary" onClick={onBack}>Back</button>
 <button className="btn-primary" onClick={handleSubmit} disabled={submitting}>
 {submitting ? "Submitting..." : "Submit Order"}
 </button>
 </div>
 </div>
 );
}
","import React, { useState } from "react";
import { useCart } from "../contexts/CartContext";
import CartItemEditor from "./CartItemEditor";
import OrderSummary from "./OrderSummary";
import { formatCurrency } from "../utils/fields";

interface Props {
 onBack: () => void;
}

export default function CartView({ onBack }: Props) {
 const { items, totalCost, clearCart } = useCart();
 const [showSummary, setShowSummary] = useState(false);

 if (showSummary) {
 return <OrderSummary onBack={() => setShowSummary(false)} onDone={onBack} />;
 }

 return (
 <div className="cart-view">
 <button className="back-btn" onClick={onBack}>← Back</button>
 <h2 className="section-title">Shopping Cart</h2>

 {items.length === 0 ? (
 <div className="cart-empty">
 <p>Your cart is empty</p>
 <button className="btn-primary" onClick={onBack}>Browse Catalog</button>
 </div>
 ) : (
 <>
 <div className="cart-items">
 {items.map((item) => (
 <div key={item.productId}>
 <CartItemEditor item={item} />
 </div>
 ))}
 </div>
 <div className="cart-footer">
 <div className="cart-total">
 <span>Total:</span>
 <strong>{formatCurrency(totalCost)}</strong>
 </div>
 <div className="cart-actions">
 <button className="btn-secondary" onClick={clearCart}>Clear Cart</button>
 <button className="btn-primary" onClick={() => setShowSummary(true)}>
 Proceed to Order
 </button>
 </div>
 </div>
 </>
 )}
 </div>
 );
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","/* ===== Catalog Section ===== */
