","import React, { useState, useEffect, useCallback } from "react";
import PortalHeader from "./components/portal/PortalHeader";
import PortalSidebar from "./components/portal/PortalSidebar";
import DashboardSection from "./components/portal/DashboardSection";
import CatalogSection from "./components/portal/CatalogSection";
import MyOrdersSection from "./components/portal/MyOrdersSection";
import DeliverySection from "./components/portal/DeliverySection";
import SurveysSection from "./components/portal/SurveysSection";
import ProfileSection from "./components/portal/ProfileSection";
import CartView from "./components/CartView";

export default function App() {
 const [section, setSection] = useState("dashboard");
 const [sidebarOpen, setSidebarOpen] = useState(true);

 useEffect(() => {
 const p = new URLSearchParams(window.location.search);
 const s = p.get("section");
 if (s) setSection(s);
 }, []);

 const navigate = useCallback((id: string) => {
 setSection(id);
 const p = new URLSearchParams(window.location.search);
 p.set("section", id);
 window.history.replaceState(null, "", `${window.location.pathname}?${p}`);
 }, []);

 const renderSection = () => {
 switch (section) {
 case "catalog":
 return <CatalogSection />;
 case "orders":
 return <MyOrdersSection />;
 case "delivery":
 return <DeliverySection />;
 case "cart":
 return <CartView onBack={() => navigate("catalog")} />;
 case "surveys":
 return <SurveysSection />;
 case "profile":
 return <ProfileSection />;
 default:
 return <DashboardSection />;
 }
 };

 return (
 <div className="portal-shell">
 <PortalHeader
 onToggleSidebar={() => setSidebarOpen(!sidebarOpen)}
 onCartClick={() => navigate("cart")}
 />
 <div className="portal-body">
 <PortalSidebar
 open={sidebarOpen}
 activeSection={section}
 onNavigate={navigate}
 />
 <main className="portal-main">{renderSection()}</main>
 </div>
 </div>
 );
}
